+
+    h1 {
+      margin: 0 0 0.75rem;
+      font-size: clamp(1.75rem, 4vw, 2.2rem);
+      line-height: 1.1;
+    }
+
+    .intro {
+      margin: 0 0 1.5rem;
+      color: var(--color-muted-text);
+      line-height: 1.5;
+    }
+
+    form {
+      display: grid;
+      gap: 1.25rem;
+    }
+
+    .form-field {
+      display: grid;
+      gap: 0.5rem;
+      padding: 1rem;
+      border: 1px solid var(--color-border);
+      border-radius: 0.875rem;
+      background: #0b1220;
+    }
+
+    .checkbox-row {
+      display: flex;
+      align-items: flex-start;
+      gap: 0.75rem;
+    }
+
+    input[type="checkbox"] {
+      width: 1.15rem;
+      height: 1.15rem;
+      margin: 0.15rem 0 0;
+      accent-color: var(--color-accent);
+      flex: none;
+    }
+
+    label {
+      font-weight: 600;
+      line-height: 1.5;
+    }
+
+    a {
+      color: var(--color-link);
+    }
+
+    .required-indicator {
+      color: var(--color-danger);
+    }
+
+    .helper-text,
+    .error-text,
+    .status-message {
+      margin: 0;
+      line-height: 1.45;
+    }
+
+    .helper-text {
+      color: var(--color-muted-text);
+      font-size: 0.95rem;
+    }
+
+    .error-text {
+      color: var(--color-danger);
+      font-size: 0.95rem;
+    }
+
+    .status-message {
+      min-height: 1.5rem;
+      color: var(--color-success);
+      font-weight: 600;
+    }
+
+    button {
+      border: 1px solid transparent;
+      border-radius: 0.875rem;
+      padding: 0.95rem 1.2rem;
+      font: inherit;
+      font-weight: 700;
+      color: #020617;
+      background: linear-gradient(135deg, #67e8f9 0%, #38bdf8 100%);
+      cursor: pointer;
+    }
+
+    button:hover {
+      filter: brightness(1.06);
+    }
+
+    a:focus-visible,
+    input[type="checkbox"]:focus-visible,
+    button:focus-visible,
+    .skip-link:focus-visible {
+      outline: 3px solid var(--color-focus);
+      outline-offset: 3px;
+    }
+
+    [hidden] {
+      display: none;
+    }
+
+    @media (max-width: 480px) {
+      .card {
+        padding: 1.5rem;
+      }
+    }
+
+    @media (forced-colors: active) {
+      .card,
+      .form-field,
+      button,
+      .skip-link {
+        border-color: ButtonBorder;
+      }
+
+      .card,
+      .form-field,
+      .skip-link {
+        background: Canvas;
+        color: CanvasText;
+      }
+
+      button {
+        background: ButtonFace;
+        color: ButtonText;
+      }
+
+      a {
+        color: LinkText;
+      }
+
+      a:focus-visible,
+      input[type="checkbox"]:focus-visible,
+      button:focus-visible,
+      .skip-link:focus-visible {
+        outline-color: Highlight;
+      }
+    }
+  </style>
+</head>
+<body>
+  <a class="skip-link" href="#main-content">Skip to main content</a>
+  <main id="main-content">
+    <section class="card" aria-labelledby="form-title">
+      <h1 id="form-title">Confirm your consent</h1>
+      <p class="intro">Please review the agreement below before continuing.</p>
+
+      <form id="consent-form" novalidate>
+        <div class="form-field">
+          <div class="checkbox-row">
+            <input
+              id="consent"
+              name="consent"
+              type="checkbox"
+              required
+              aria-describedby="consent-help consent-error"
+            >
+            <label for="consent">
+              I agree to the terms of use <span class="required-indicator" aria-hidden="true">*</span>
+            </label>
+          </div>
+          <p id="consent-help" class="helper-text">Required to continue.</p>
+          <p id="consent-error" class="error-text" hidden>Error: Agree to the terms of use before submitting.</p>
+        </div>
+
+        <button type="submit">Continue</button>
+        <p id="form-status" class="status-message" aria-live="polite"></p>
+      </form>
+    </section>
+  </main>
+
+  <script>
+    const form = document.getElementById('consent-form');
+    const consent = document.getElementById('consent');
+    const error = document.getElementById('consent-error');
+    const status = document.getElementById('form-status');
+
+    const clearError = () => {
+      consent.removeAttribute('aria-invalid');
+      error.hidden = true;
+    };
+
+    form.addEventListener('submit', (event) => {
+      event.preventDefault();
+
+      if (!consent.checked) {
+        consent.setAttribute('aria-invalid', 'true');
+        error.hidden = false;
+        status.textContent = '';
+        consent.focus();
+        return;
+      }
+
+      clearError();
+      status.textContent = 'Consent recorded. You can continue.';
+    });
+
+    consent.addEventListener('change', () => {
+      if (consent.checked) {
+        clearError();
+      }
+    });
+  </script>
+</body>
+</html>
*** End Patch
